			graphics.setColor(new Color(255, 205, 130));
			graphics.fillOval(4, 3, 8, 8);
			graphics.setColor(Color.WHITE);
			graphics.setStroke(new BasicStroke(2f));
			graphics.drawArc(3, 6, 10, 7, 200, 140);
