package com.faceswap;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

final class FullFaceHeadItems
{
	private static final String RESOURCE = "/full_face_head_items.csv";
	private static final Set<Integer> ITEM_IDS = load();

	private FullFaceHeadItems()
	{
	}

	static boolean contains(int itemId)
	{
		return ITEM_IDS.contains(itemId);
	}

	static int size()
	{
		return ITEM_IDS.size();
	}

	private static Set<Integer> load()
	{
		InputStream stream = FullFaceHeadItems.class.getResourceAsStream(RESOURCE);
		if (stream == null)
		{
			throw new IllegalStateException("Missing full-face item resource " + RESOURCE);
		}

		Set<Integer> itemIds = new HashSet<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			String header = reader.readLine();
			if (!"item_id,item_name".equals(header))
			{
				throw new IllegalStateException("Unexpected full-face item header: " + header);
			}

			String line;
			while ((line = reader.readLine()) != null)
			{
				if (!line.isBlank())
				{
					itemIds.add(Integer.parseInt(line.substring(0, line.indexOf(','))));
				}
			}
		}
		catch (IOException | NumberFormatException ex)
		{
			throw new IllegalStateException("Unable to load full-face items", ex);
		}
		return Collections.unmodifiableSet(itemIds);
	}
}

package com.faceswap;

final class HelmetCalibration
{
	private static final int MIN_OFFSET = -128;
	private static final int MAX_OFFSET = 128;
	private static final int MIN_SCALE = 25;
	private static final int MAX_SCALE = 250;
	private static final int MIN_DIMENSION = 50;
	private static final int MAX_DIMENSION = 200;

	private int y;
	private int scale;
	private int x;
	private int z;
	private int pitch;
	private int yaw;
	private int roll;
	private int width;
	private int faceHeight;
	private int depth;
	private int animationFrameOffset;
	private HelmetMeshCalibration meshCalibration;

	private HelmetCalibration(
		int y,
		int scale,
		int x,
		int z,
		int pitch,
		int yaw,
		int roll,
		int width,
		int faceHeight,
		int depth,
		int animationFrameOffset)
	{
		this.y = clamp(y, MIN_OFFSET, MAX_OFFSET);
		this.scale = clamp(scale, MIN_SCALE, MAX_SCALE);
		this.x = clamp(x, MIN_OFFSET, MAX_OFFSET);
		this.z = clamp(z, MIN_OFFSET, MAX_OFFSET);
		this.pitch = clamp(pitch, -180, 180);
		this.yaw = clamp(yaw, -180, 180);
		this.roll = clamp(roll, -180, 180);
		this.width = clamp(width, MIN_DIMENSION, MAX_DIMENSION);
		this.faceHeight = clamp(faceHeight, MIN_DIMENSION, MAX_DIMENSION);
		this.depth = clamp(depth, MIN_DIMENSION, MAX_DIMENSION);
		this.animationFrameOffset = clamp(animationFrameOffset, -3, 3);
		this.meshCalibration = new HelmetMeshCalibration();
	}

	static HelmetCalibration fromConfig(FaceSwapConfig config)
	{
		return new HelmetCalibration(
			config.prototype3dY(),
			config.prototype3dScale(),
			config.prototype3dX(),
			config.prototype3dZ(),
			config.prototype3dPitch(),
			config.prototype3dYaw(),
			config.prototype3dRoll(),
			config.prototype3dWidth(),
			config.prototype3dFaceHeight(),
			config.prototype3dDepth(),
			config.prototypeAnimationFrameOffset());
	}

	static HelmetCalibration fromProfileOrConfig(HelmetProfile profile, FaceSwapConfig config)
	{
		if (profile == null || !profile.isTested())
		{
			return fromConfig(config);
		}

		return new HelmetCalibration(
			profile.getModelY(),
			profile.getModelScale(),
			profile.getModelX(),
			profile.getModelZ(),
			profile.getModelPitch(),
			profile.getModelYaw(),
			profile.getModelRoll(),
			profile.getModelWidth(),
			profile.getModelFaceHeight(),
			profile.getModelDepth(),
			profile.getAnimationFrameOffset());
	}

	HelmetCalibration copy()
	{
		HelmetCalibration copy = new HelmetCalibration(y, scale, x, z, pitch, yaw, roll, width, faceHeight, depth,
			animationFrameOffset);
		copy.meshCalibration = meshCalibration.copy();
		return copy;
	}

	void setMeshCalibration(HelmetMeshCalibration meshCalibration)
	{
		this.meshCalibration = meshCalibration == null ? new HelmetMeshCalibration() : meshCalibration.copy();
	}

	HelmetMeshCalibration getMeshCalibration()
	{
		return meshCalibration.copy();
	}

	void applyMeshDrag(MeshControlPoint point, float deltaX, float deltaY)
	{
		meshCalibration.applyDrag(point, deltaX, deltaY);
	}

	void adjustMeshDepth(MeshControlPoint point, int wheelRotation)
	{
		meshCalibration.adjustDepth(point, wheelRotation);
	}

	void applyDrag(CalibrationHandle handle, int deltaX, int deltaY)
	{
		int horizontal = Math.round(deltaX / 2f);
		int vertical = Math.round(deltaY / 2f);
		switch (handle)
		{
			case MOVE:
				x = clamp(x + horizontal, MIN_OFFSET, MAX_OFFSET);
				y = clamp(y - vertical, MIN_OFFSET, MAX_OFFSET);
				break;
			case WIDTH:
				width = clamp(width + horizontal, MIN_DIMENSION, MAX_DIMENSION);
				break;
			case HEIGHT:
				faceHeight = clamp(faceHeight - vertical, MIN_DIMENSION, MAX_DIMENSION);
				break;
			case SCALE:
				scale = clamp(scale + horizontal, MIN_SCALE, MAX_SCALE);
				break;
			case DEPTH:
				depth = clamp(depth + horizontal, MIN_DIMENSION, MAX_DIMENSION);
				break;
			default:
				break;
		}
	}

	void adjustZ(int wheelRotation)
	{
		z = clamp(z - wheelRotation, MIN_OFFSET, MAX_OFFSET);
	}

	int getY()
	{
		return y;
	}

	int getScale()
	{
		return scale;
	}

	int getX()
	{
		return x;
	}

	int getZ()
	{
		return z;
	}

	int getPitch()
	{
		return pitch;
	}

	int getYaw()
	{
		return yaw;
	}

	int getRoll()
	{
		return roll;
	}

	int getWidth()
	{
		return width;
	}

	int getFaceHeight()
	{
		return faceHeight;
	}

	int getDepth()
	{
		return depth;
	}

	int getAnimationFrameOffset()
	{
		return animationFrameOffset;
	}

	private static int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}
}

package com.faceswap;

import java.util.EnumMap;
import java.util.Map;

/** Local weighted offsets for the stable landmarks on one helmet profile. */
final class HelmetMeshCalibration
{
	private static final int MIN_OFFSET = -32;
	private static final int MAX_OFFSET = 32;
	private static final float INFLUENCE_RADIUS_X = 8f;
	private static final float INFLUENCE_RADIUS_Y = 9f;
	private static final float INFLUENCE_RADIUS_Z = 11f;
	private final Map<MeshControlPoint, Offset> offsets = new EnumMap<>(MeshControlPoint.class);

	HelmetMeshCalibration()
	{
		for (MeshControlPoint point : MeshControlPoint.values())
		{
			offsets.put(point, new Offset());
		}
	}

	HelmetMeshCalibration copy()
	{
		HelmetMeshCalibration copy = new HelmetMeshCalibration();
		for (MeshControlPoint point : MeshControlPoint.values())
		{
			Offset offset = offsets.get(point);
			copy.offsets.put(point, new Offset(offset.x, offset.y, offset.z));
		}
		return copy;
	}

	void applyDrag(MeshControlPoint point, int deltaX, int deltaY)
	{
		applyDrag(point, (float) deltaX, (float) deltaY);
	}

	void applyDrag(MeshControlPoint point, float deltaX, float deltaY)
	{
		if (point == null)
		{
			return;
		}
		Offset offset = offsets.get(point);
		offset.x = clamp(offset.x + deltaX);
		// Model Y increases downward in RuneLite's model coordinates, matching
		// the canvas Y direction used by the calibration overlay.
		offset.y = clamp(offset.y + deltaY);
	}

	void adjustDepth(MeshControlPoint point, int wheelRotation)
	{
		if (point != null)
		{
			Offset offset = offsets.get(point);
			offset.z = clamp(offset.z - wheelRotation);
		}
	}

	void setOffset(MeshControlPoint point, int x, int y, int z)
	{
		if (point != null)
		{
			offsets.put(point, new Offset(clamp(x), clamp(y), clamp(z)));
		}
	}

	int getX(MeshControlPoint point)
	{
		return Math.round(offsets.get(point).x);
	}

	float getXOffset(MeshControlPoint point)
	{
		return offsets.get(point).x;
	}

	int getY(MeshControlPoint point)
	{
		return Math.round(offsets.get(point).y);
	}

	float getYOffset(MeshControlPoint point)
	{
		return offsets.get(point).y;
	}

	int getZ(MeshControlPoint point)
	{
		return offsets.get(point).z;
	}

	private static float clamp(float value)
	{
		return Math.max(MIN_OFFSET, Math.min(MAX_OFFSET, value));
	}

	boolean isDefault()
	{
		for (Offset offset : offsets.values())
		{
			if (offset.x != 0 || offset.y != 0 || offset.z != 0)
			{
				return false;
			}
		}
		return true;
	}

	String key()
	{
		StringBuilder key = new StringBuilder();
		for (MeshControlPoint point : MeshControlPoint.values())
		{
			Offset offset = offsets.get(point);
			key.append(':').append(offset.x).append(':').append(offset.y).append(':').append(offset.z);
		}
		return key.toString();
	}

	/** Applies smooth local movement to the generated logical head vertices. */
	void applyTo(float[] verticesX, float[] verticesY, float[] verticesZ)
	{
		for (int vertex = 0; vertex < verticesX.length; vertex++)
		{
			// The final logical vertex is the neck seam and must remain anchored.
			if (vertex == verticesX.length - 1)
			{
				continue;
			}
			float totalWeight = 0f;
			float offsetX = 0f;
			float offsetY = 0f;
			float offsetZ = 0f;
			for (MeshControlPoint point : MeshControlPoint.values())
			{
				Offset offset = offsets.get(point);
				float dx = (verticesX[vertex] - point.getX()) / INFLUENCE_RADIUS_X;
				float dy = (verticesY[vertex] - point.getY()) / INFLUENCE_RADIUS_Y;
				float dz = (verticesZ[vertex] - point.getZ()) / INFLUENCE_RADIUS_Z;
				float weight = (float) Math.exp(-0.5f * (dx * dx + dy * dy + dz * dz));
				if (weight < 0.01f)
				{
					continue;
				}
				totalWeight += weight;
				offsetX += weight * offset.x;
				offsetY += weight * offset.y;
				offsetZ += weight * offset.z;
			}
			if (totalWeight > 0f)
			{
				verticesX[vertex] += offsetX / totalWeight;
				verticesY[vertex] += offsetY / totalWeight;
				verticesZ[vertex] += offsetZ / totalWeight;
			}
		}
	}

	private static int clamp(int value)
	{
		return Math.max(MIN_OFFSET, Math.min(MAX_OFFSET, value));
	}

	private static final class Offset
	{
		private float x;
		private float y;
		private int z;

		private Offset()
		{
		}

		private Offset(float x, float y, int z)
		{
			this.x = x;
			this.y = y;
			this.z = z;
		}
	}
}

